architecture.h4_f:
msg = CBOR{v:1، ޓެކްސްޓް، ރިޕްލައި_ޓު، ސެންޑް_އެޓް}
ct = AES-GCM-256-އެންކްރިޕްޓް(k, nonce, msg, aad=room_id)
POST /api/rooms/{id}/messages {ސައިފަރޓެކްސްޓް: ހެކްސް(ސީޓީ)، ނޮންސް: ހެކްސް}

cryptoWire.h1_f:
pt = CBOR{v:1، ޓެކްސްޓް، ރިޕްލައި_ޓު؟، ތްރެޑް_އައިޑީ؟، މެންޝަންސް؟، ސެންޑް_އެޓް}
ct = AES-GCM-256-އެންކްރިޕްޓް(ރޫމް_ކީ، ނޮންސް، ޕީޓީ، އާޑް=ހެކްސް(ރޫމް_އައިޑީ))
ވަޔަރ = CBOR{
  v: 1،
  ciphertext: hex(ct), // ވެރިއޭބަލް ދިގުމިން
  nonce: ހެކްސް(12 ބީ)،
  ސެންޑަރ_ސޫޑޯ: ހެކްސް(16 ބީ)،
  sent_at: ޔުނިކްސް_އެމްއެސް
}

cryptoWire.h5_f:
ބޭރު = CBOR{
  ސޯސް_ނޯޑް: hex32,
  ޓާގެޓް_ޔޫޒަރ: int64،
  inner_ciphertext: ބައިޓްސް،
  inner_nonce: ބައިޓްސް،
  sent_at: ޔުނިކްސް_އެމްއެސް
}
sig = Ed25519-Sign(ސޯސް_ޕްރައިވް، ބޭރު)
POST /federation/deliver { ސިޓީއުރަ: ބޭރު، ސިގް: hex64 }

auth.h1_f:
POST /api/އޮތެންޓިކޭޝަން/ރެޖިސްޓަރ
  { ޔޫޒަރނޭމް، ޕާސްވޯޑް، x25519_ޕަބްލިކް_ކީ، ޑިސްޕްލޭ_ނަން، ފޯނު؟، އީމެއިލް؟، އަވަޓަރ_އިމޯޖީ }

ޖަވާބު 201 އުފެއްދީ:
  { އެކްސެސް_ޓޯކަން، ރިފްރެޝް_ޓޯކަން، ޔޫޒަރ_އައިޑީ، ޔޫޒަރނޭމް، ... }

auth.h3_f:
access_token ޕޭލޯޑް:
  { sub: ޔޫޒަރ_އައިޑީ، jti: ޑިވައިސް_އައިޑީ، ޓައިޕް: "އެކްސެސް", exp: މިހާރު + 15min }
refresh_token ޕޭލޯޑް:
  { ސަބް: ޔޫޒަރ_އައިޑީ، ޖީޓީއައި: ޑިވައިސް_އައިޑީ، ޓައިޕް: "ރިފްރެޝް"، އެކްސްޕް: މިހާރު + 30ޑީ }

HS256-ސޮއިކޮށްފައިވަނީ ނޯޑްގެ 64 ބައިޓްގެ ސިއްރު .env އިންނެވެ

auth.h4_f:
ރެޖިސްޓަރ_ބެގިން(): ޗެލެންޖް = ރެންޑް(32)
                    options = { rp.id، ޔޫޒަރ.އައިޑީ، ޕަބްކީކްރެޑްޕެރަމްސް، ޗެލެންޖް }
                    ރިޓަރން އޮޕްޝަންސް

ރެޖިސްޓަރ_ފިނިޝް(އެޓެސްޓޭޝަން):
  TPM އާ ދެކޮޅަށް އެޓެސްޓޭޝަން ޔަގީންކުރުން / ސެކިއުރިޓީ އެންކްލޭވް ރޫޓް CA
  store { ކްރެޑެންޝަލް_އައިޑީ، ޕަބްލިކް_ކީ، ކައުންޓަރ: 0 }

auth.h7_f:
POST /api/އޮތެންޓިކޭޝަން/qr/ފެށުން
  → { nonce: 128-ބިޓް ހެކްސް، ttl: 60 }
QR ޕޭލޯޑް = { ނޮންސް، ޔޫޒަރ_އައިޑީ، ސަރވަރ: "https://node.example" }

POST /api/އޮތެންޓިކޭޝަން/qr/ވެރިފައި { nonce }
  → އާ ޑިވައިސް ރަޖިސްޓްރީ ކުރެވިފައިވުން؛ ޖޭޑަބްލިޔުޓީސް އެނބުރި އައެވެ.

rooms.h6_f:
ސެންޑަރ_ސޫޑޯ = HMAC-SHA256(ރޫމް_ސޫޑޯ_ސޮލްޓް، ސެންޑަރ_އައިޑީ)[:16] // 32 ހެކްސް
ciphertext = AES-GCM-އެންކްރިޕްޓް(ރޫމް_ކީ، ނޮންސް، ސީބީއޯއާރު_ޕޭލޯޑް، އޭއޭޑީ=ރޫމް_އައިޑީ)

ފޭން-އައުޓް ފްރޭމް: { ޓައިޕް:"އެމް", ރޫމް، އެމްއެސްޖީ:{އައިޑީ، ސީޓީ، ނޮންސް، ސެންޑަރ_ސޫޑޯ، ސެންޑް_އެޓް} }

files.h2_f:
init POST /api/files/resumible/init {ފައިލް ނަން، ސައިޒް، ޗަންކް_ސައިޒް_ހިންޓް}
            ← {އަޕްލޯޑް_އައިޑީ، ޗަންކް_ސައިޒް}
ޗަންކް PUT /api/ފައިލްސް/ރީޒުމަބަލް/{އަޕްލޯޑް_އައިޑީ}/ޗަންކް/{އޮފްސެޓް} <ސީޓީ ބައިޓްސް>
            ← 204
ފައިނަލައިޒް POST /api/ފައިލްސް/ރީޒުމަބަލް/{އަޕްލޯޑް_އައިޑީ}/ފައިނަލައިޒް {ޕްލޭން_ބްލޭކް3}
            ← 201 {ފައިލް_އައިޑީ، ޔޫއާރްއެލް}
TTL ނުނިމިގެން: 24 ހ

files.h4_f:
އިންކާރު_ލިސްޓް = {
  "އެޕްލިކޭޝަން/އެކްސް-ޑޮސެކްސެކް"،
  "އެޕްލިކޭޝަން/އެކްސް-ޝެއަރޑްލިބް"،
  "އެޕްލިކޭޝަން/އެކްސް-މެކް-ބައިނަރީ"،
}
if magic.from_buffer(buf[:1024]) in deny_list: ރިޓަރން 415

presence.h1_f:
ކްލައިންޓް: ފުރަތަމަ ކީސްޓްރޯކްގައި → ފޮނުވާ {type:"t", state:"start"}
         ސްޓޭޓް ބަދަލުވެގެން ނޫނީ 3 s އަށް އިތުރަށް ނުފޮނުވައެވެ
         އެންމެ ފަހުން ކީސްޓްރޯކް ކުރިތާ 10 s → ފޮނުވާ {type:"t", state:"stop"}
ރިސީވަރ: އެންމެ ފަހުން "ސްޓާޓް" އަށް ފަހު 10 s ފަހުން އޮޓޯ-ސްޓޮޕް "ސްޓޮޕް" އެއް ނުލިބިއްޖެނަމަ

calls.h1_f:
POST /api/calls/{room_id}/ސްޓާޓް {ވީޑިއޯ، އޯޑިއޯ} → ކޯލް_އައިޑީ
WS ބްރޯޑްކާސްޓް {ވައްތަރު:"ސީ", ވައްތަރު:"ދައުވަތު ދިނުން", ކޯލް_އައިޑީ}
WS ބްރޯޑްކާސްޓް {ޓައިޕް:"c", ވައްތަރު:"އޮފާ", sdp}
WS ބްރޯޑްކާސްޓް {ވައްތަރު:"c", ވައްތަރު:"ޖަވާބު", sdp}
WS ބްރޯޑްކާސްޓް {ވައްތަރު:"c", ބާވަތް:"ކެންޑިޑޭޓް",އައިސް} × ނ
POST /api/colls/{coll_id}/ނިމުނީ

federation.h2_f:
ސިޓީއުރަ = {
  ސޯސް_ނޯޑް : hex32,
  ޓާގެޓް_ޔޫޒަރ : int64,
  inner_ciphertext: ބައިޓްސް،
  inner_nonce : ބައިޓްސް،
  sent_at : ޔުނިކްސް_އެމްއެސް،
}
sig = Ed25519Sign(ސޯސް_ޕްރައިވް، CBOR(އުރަ އުރަ))
POST /ފެޑެރޭޝަން/ޑެލިވަރ { ސިޓީއުރަ، ސިގް }

stealth.h2_f:
ކްލައިންޓްހެލޯ ބައިޓްސް = chrome_120_template with {
  ރެންޑަމް = އަހަރެމެންގެ ރެންޑަމް،
  server_name = އަހަރެމެންގެ ހޯސްޓްނަން (ނުވަތަ ECH-wrapped)،
  session_id = އަހަރެމެންގެ ސެޝަން އައިޑީ،
}
JA4 = t13d_xxxx_xxxx_xxxx (މިހާރު ކްރޯމް ސްޓޭބަލް އާއި އެއްގޮތް)

stealth.h4_f:
DoH: POST https://cloudflare-dns.com/dns-query {ނަން: އެކްސް.ވޯރޓެކްސް.ސޮލް}
ECH: ކްލައިންޓްހެލޯ.އެކްސްޓެންޝަންސް += އެންކްރިޕްޓްޑް_ސްނީ(ޕަބްލިކް_ކީ_ފްރޮމް_އެޗްޓީޓީޕީއެސް_ރެކޯޑް)
DGA: ޑޮމެއިން(t) = base32( SHA256(އޮށް ∥ YYYY-MM-DD) )[:16] + ".މިސާލު"

push.h4_f:
އައިއޯއެސް NSE: didReceive(request) { decrypt(ރިކުއެސްޓް.ކޮންޓެންޓް.ޔޫޒަރއިންފޯ) }
އެންޑްރޮއިޑް FCM: onMessageReceived(remoteMessage) { ޑިކްރިޕްޓް(ރިމޯޓްމެސެޖް.ޑޭޓާ) }
ވެބް SW: self.addEventListener('ޕުޝް'، އީ => ޑިކްރިޕްޓް(އީ.ޑޭޓާ))

controller.h2_f:
ޓޫލް = ސައިން_ޓޫލް
input = ސޯސް ޓްރީ، ކީސް/ރިލީޒް.ކީ
މެނިފެސްޓް = {
  ވަރޝަން: "0.1.0"،
  ބިލްޓް_އެޓް: ޔުނިކްސް_އެމްއެސް،
  ފައިލްތައް: [{path, sha256, size}, ...]
}
sig = Ed25519-Sign(ރިލީޒް_ޕްރައިވް، CBOR(މެނިފެސްޓް))
އައުޓްޕުޓް = INTEGRITY.sig.json = {މެނިފެސްޓް، ސޮއިކޮށްފައިވަނީ: ޕަބް_ހެކްސް، ސިގް: ސިގް_ހެކްސް}

bots.h1_f:
އުފެއްދުން: POST /api/bots {ޔޫޒަރނޭމް، ޑިސްޕްލޭ_ނަން، ކޯޑް}
          → {ބޮޓް_އައިޑީ، ޓޯކަން، ޕަބްކީ}
ރަން: އިން-ޕްރޮސެސް (ކޯރޫޓިން އިންސައިޑް ނޯޑް)
      OR ބޭރު (ލޯންގް-ޕޯލް /api/bots/{id}/updates, token-auth'd)
މެސެޖް: {ޓެކްސްޓް، ސޮއި: Ed25519-Sign(bot_priv, canonical_msg)}

bots.h2_f:
on /start {
  emit "މަރުހަބާ، {ctx.first_name}"
}
on /އެޑް <އައިޓަމް> {
  state.list = (ސްޓޭޓް.ލިސްޓް ނުވަތަ []) + [ctx.args.item]
  emit "އެޑްޑް: {ctx.args.item}"
}

security.h4_f:
canary.txt (ދުވާލަކު):
  {ތާރީޚު، ސިގް: Ed25519-Sign(ރިލީޒް_ޕްރައިވް، ތާރީޚް)}
ކްލައިންޓް ޔަގީންކުރުން → ނެތް ނުވަތަ ސައްހަ ނޫން ⇒ ކޮމްޕްރޮމައިޒް ޝައްކުކުރެވޭ

ކުއްލި ހާލަތުގައި:
  އެޑްމިން POST /api/admin/revoke-all {ސަބަބު}
  ނޯޑް ބްރޯޑްކާސްޓްސް {ޓައިޕް:"n", އިވެންޓް:"ކޮމްޕްރޮމައިޒް", ސަބަބު}
  ކްލައިންޓުން ކީ ފޮހެލާ، ފޯސް ރީ ބޫޓްސްޓްރަޕް

debugging.h2_f:
ރޭޓް ހިސްޓޯގްރާމްސް (ރޫޓަކަށް + މެތޯޑަކަށް):
  vortex_http_requests_total{ރޫޓް،މެތޯޑް،ސްޓޭޓަސް}
  vortex_http_request_duration_seconds_bucket{ރޫޓް،މެތޯޑް،ލެ}

ވެބްސޮކެޓް ގޭޖްތައް:
  ވޯރޓެކްސް_ޑަބްލިއުއެސް_ކަނެކްޝަންސް{ނޯޑް}
  vortex_ws_fanout_queue_depth{ކޮޓަރި،ޔޫޒަރ}

ކަސްޓަމް ކައުންޓަރުތައް:
  ވޯރޓެކްސް_މެސެޖްސް_ސެންޓް_ޓޯޓަލް{ރޫމް_ޓައިޕް}
  ވޯރޓެކްސް_ކޯލްސް_ސްޓާޓްޑް_ޓޯޓަލް{ކައިންޑް}

login.h3_f:
{
  "ޔޫޒަރނޭމް": "އެލިސް"،
  "ޕާސްވޯޑް": "ރަނގަޅު އަސް ބެޓެރީ ސްޓޭޕްލް"،
  "totp": "123456" // 2އެފްއޭ އެނެބަލް ކޮށްފިނަމަ ބޭނުންވާނެއެވެ
}

login.h4_f:
ކާމިޔާބީގެ މައްޗަށް: 201 + JWT ސިޓީއުރަ (ރެޖިސްޓަރ އާއި އެއް ބައްޓަމެއް)
on 2FA needed: 200 { "needs_2fa": true } (އަދި JWT އެއް ނެތް)
on failure: 401 { "error":"invalid_credentials" }

apns.h1_f:
POST https://api.push.apple.com/3/ޑިވައިސް/<ޑިވައިސް_ޓޯކަން>
ހެޑަރސް: އެޕްންސް-ޓޮޕިކް: <ބަންޑްލް_އައިޑީ>، އެޕްންސް-ޕުޝް-ޓައިޕް: އެލާޓް، އެޕްންސް-ކޮލަޕްސް-އައިޑީ: ރޫމް:42
ބޮޑީ: {aps: {އެލާޓް: {ޓައިޓަލް، ބޮޑީ}}، ޑޭޓާ: <ސީލްޑް>}

bmp.h1_f:
mailbox_id = HKDF(ރިސީވަރ_ޕަބްކީ، އިންފޯ="bmp-v1", len=32)
ޑިޕޮސިޓް: POST /bmp/deposit {mailbox_id, blob ≤1MB}
ޕިކަޕް: GET /bmp/messages (auth'd)

controller.h1_f:
GET /v1/integrity → {ސްޓޭޓަސް، ސައިންޑް_ބައި، މެޗްޑް، މިސްމެޗްޑް، ...}
GET /v1/health → {ސްޓޭޓަސް، ވަރޝަން، ޕަބްކީ، ސްޓެޓިސްޓިކްސް}
GET /v1/އެންޓްރީސް → [{ޕްރޮޓޮކޯލް، ޔޫއާރްއެލް}، ...]
GET /v1/mirrors → [ކޮންޓްރޯލަރ_އުރލް، ...]

fcm.h1_f:
POST https://fcm.googleapis.com/v1/ޕްރޮޖެކްޓްސް/<ޕްރޮޖެކްޓް>/މެސެޖްސް:ފޮނުވުން
ހުއްދަ: ބެއަރ <oauth2_token>
ބޮޑީ: {މެސެޖް: {ޓޯކަން: <ޑިވައިސް>، ޑޭޓާ: {...ސީލްޑް...}، އެންޑްރޮއިޑް: {ކޮލަޕްސް_ކީ}}}

federation.h1_f:
އެންވެލޯޕް = {ސޯސް_ނޯޑް، ޓާގެޓް_ޔޫޒަރ، އިނަރ_ސީޓީ، އިނަރ_ނޮންސް، ސެންޑް_އެޓް}
sig = Ed25519-Sign(ސޯސް_ޕްރައިވް، CBOR(އުރަ އުރަ))
POST /ފެޑެރޭޝަން/ޑެލިވަރ {އުރަ އުރަ، ސިގް}
ބީ ވެރިފައިސް: ސިގް އެގޭންސް ފެޑެރޭޝަންސް[ސޯސް_ނޯޑް].ޕަބްކީ

fts5.h1_f:
CREATE VIRTUAL TABLE މެސެޖް_ފޫޓްސް USING ފޫޓް5(
  ކޮންޓެންޓް، -- ޓޯކެނައިޒްޑް ކޮލަމް
  ރޫމް_އައިޑީ UNINDEXED،
  tokenize = 'ޔުނިކޯޑް61 ރިމޫވް_ޑައިކްރިޓިކްސް 2'.
);
ސުވާލު: SELECT ރޯވިޑް FROM މެސެޖްސް_ފްޓްސް WHERE ކޮންޓެންޓް MATCH 'ފޫ'.

gravitix.h1_f:
on /start { emit "މަރުހަބާ، {ctx.first_name}" }
on /އެޑް <އައިޓަމް> {
  state.list = (ސްޓޭޓް.ލިސްޓް ނުވަތަ []) + [ctx.args.item]
  emit "އެޑްޑް: {ctx.args.item}"
}

prekey.h1_f:
ބަންޑަލް = {
  އައިޑެންޓިޓީ_ޕީކޭ،
  ސޮއިކޮށްފައިވަނީ_ޕްރީކީ_ޕީކޭ،
  signed_prekey_sig = Ed25519-Sign(އައިޑެންޓިޓީ_ޕްރައިވް، ސޮއިކޮށްފައިވާ_ޕްރީކީ_ޕީކޭ)،
  އެއްފަހަރު_ޕްރީކީސް: [pk_0، pk_1، ...، pk_9]
}

vapid.h1_f:
VAPID ކީސް: ކޮންމެ ނޯޑަކަށް Ed25519 ކީޕެއާ
sign JWT: {aud: push_service_origin, exp: މިހާރު + 12h, sub: mailto:ops@example}
ޕުޝް ރިކުއެސްޓް ހެޑަރސް: ހުއްދަ: vapid t=<jwt>، k=<vapid_public_key>
